INSERT INTO question (id, title, competence_id, description, tooltip_data, type, created_at, updated_at, deleted_at, scale) VALUES ('a235ad6f-382b-4865-94f7-ac5e53736ec6', 'Les élèves sont en activité', '4d15a3be-db2a-4fef-913a-6535bcd9d389', 'Dans les 10 premières minutes du cours', '{"title":"Les élèves ne travaillent pas","subtitle":"Considérez qu''un élève ne participe pas s''il est trop distrait ou perturbe la classe","items":[{"icon":"chart-down","label":"Faible","description":"La plupart des élèves ne travaillent pas"},{"icon":"heart-rate","label":"Moyen","description":"Certains élèves travaillent"},{"icon":"arrow-growth","label":"Élevé","description":"La plupart des élèves travaillent"}]}', 'option', NULL, NULL, NULL, 3) ON CONFLICT DO NOTHING;
INSERT INTO question (id, title, competence_id, description, tooltip_data, type, created_at, updated_at, deleted_at, scale) VALUES ('cf1c6bc7-d5ed-4de8-9fb3-fb3c20cca23e', 'Les élèves sont en activité', '4d15a3be-db2a-4fef-913a-6535bcd9d389', 'Dans les 10 minutes suivantes du cours', '{"title":"Les élèves ne travaillent pas","subtitle":"Considérez qu''un élève ne participe pas s''il est trop distrait ou perturbe la classe","items":[{"icon":"chart-down","label":"Faible","description":"La plupart des élèves ne travaillent pas"},{"icon":"heart-rate","label":"Moyen","description":"Certains élèves travaillent"},{"icon":"arrow-growth","label":"Élevé","description":"La plupart des élèves travaillent"}]}', 'option', NULL, NULL, NULL, 3) ON CONFLICT DO NOTHING;
INSERT INTO question (id, title, competence_id, description, tooltip_data, type, created_at, updated_at, deleted_at, scale) VALUES ('9b2391ed-9643-4d8c-a360-58251ea4f0e6', 'Les élèves sont en activité', '4d15a3be-db2a-4fef-913a-6535bcd9d389', 'Dans les 10 dernières minutes du cours', '{"title":"Les élèves ne travaillent pas","subtitle":"Considérez qu''un élève ne participe pas s''il est trop distrait ou perturbe la classe","items":[{"icon":"chart-down","label":"Faible","description":"La plupart des élèves ne travaillent pas"},{"icon":"heart-rate","label":"Moyen","description":"Certains élèves travaillent"},{"icon":"arrow-growth","label":"Élevé","description":"La plupart des élèves travaillent"}]}', 'option', NULL, NULL, NULL, 3) ON CONFLICT DO NOTHING;
INSERT INTO question (id, title, competence_id, description, tooltip_data, type, created_at, updated_at, deleted_at, scale) VALUES ('b635e130-7d71-44a8-905b-134ca55adaef', 'Tous les élèves sont traités avec respect', '0f8d1dcb-1d26-4073-a184-80e32012ae1b', NULL, '{"title":"Tous les élèves sont traités avec respect","subtitle":"Le traitement est irrespectueux si l''enseignant crie, humilie ou recourt à des punitions corporelles","items":[{"icon":"chart-down","label":"Faible","description":"L''enseignant est irrespectueux envers les élèves"},{"icon":"heart-rate","label":"Moyen","description":"L''enseignant n''est pas clairement irrespectueux mais peu poli"},{"icon":"arrow-growth","label":"Élevé","description":"L''enseignant est poli, appelle les élèves par leur prénom, dit s''il vous plaît et merci"}]}', 'option', NULL, NULL, NULL, 5) ON CONFLICT DO NOTHING;
INSERT INTO question (id, title, competence_id, description, tooltip_data, type, created_at, updated_at, deleted_at, scale) VALUES ('dd3d2cd1-d87e-4f34-b63b-6ffdeebb0170', 'L''enseignant utilise un langage positif', '0f8d1dcb-1d26-4073-a184-80e32012ae1b', NULL, '{"title":"L''enseignant utilise un langage positif","subtitle":"Le langage est négatif s''il exprime de la frustration ou décourage les élèves","items":[{"icon":"chart-down","label":"Faible","description":"L''enseignant utilise un langage négatif"},{"icon":"heart-rate","label":"Moyen","description":"L''enseignant utilise parfois un langage positif"},{"icon":"arrow-growth","label":"Élevé","description":"L''enseignant utilise un langage positivement encourageant"}]}', 'option', NULL, NULL, NULL, 5) ON CONFLICT DO NOTHING;
INSERT INTO question (id, title, competence_id, description, tooltip_data, type, created_at, updated_at, deleted_at, scale) VALUES ('830808c5-dc47-462a-8080-c31f953aad02', 'L''enseignant répond aux besoins des élèves', '0f8d1dcb-1d26-4073-a184-80e32012ae1b', NULL, '{"title":"L''enseignant répond aux besoins des élèves","subtitle":"Les besoins peuvent concerner le matériel, l''aide ou la compréhension d''une leçon","items":[{"icon":"chart-down","label":"Faible","description":"L''enseignant ne voit pas les besoins ou n''agit pas"},{"icon":"heart-rate","label":"Moyen","description":"L''enseignant répond mais ne règle pas le problème"},{"icon":"arrow-growth","label":"Élevé","description":"L''enseignant répond rapidement et règle les besoins"}]}', 'option', NULL, NULL, NULL, 5) ON CONFLICT DO NOTHING;
INSERT INTO question (id, title, competence_id, description, tooltip_data, type, created_at, updated_at, deleted_at, scale) VALUES ('6779b8e9-da1d-4c3a-8691-53c6233a914d', 'Tous les groupes de genre sont traités équitablement', '0f8d1dcb-1d26-4073-a184-80e32012ae1b', NULL, '{"title":"Équité entre les groupes de genre","subtitle":"Inéquitable si les occasions de participer ou les attentes diffèrent selon le genre","items":[{"icon":"chart-down","label":"Faible","description":"Traitement inéquitable selon le genre"},{"icon":"heart-rate","label":"Moyen","description":"Pas d''inéquité flagrante mais pas d''effort explicite"},{"icon":"arrow-growth","label":"Élevé","description":"Équité claire et expliquée aux élèves"}]}', 'option', NULL, NULL, NULL, 5) ON CONFLICT DO NOTHING;
INSERT INTO question (id, title, competence_id, description, tooltip_data, type, created_at, updated_at, deleted_at, scale) VALUES ('97a48f96-cd27-4879-8f41-d2f4ff263785', 'Des attentes comportementales claires sont fixées pour les activités', 'b9f2de44-2825-4353-a092-e979b7190a28', NULL, '{"title":"Attentes comportementales claires","subtitle":"Si le comportement n''est pas bon, l''enseignant doit rappeler les règles attendues pendant la leçon","items":[{"icon":"chart-down","label":"Faible","description":"Aucune attente claire n''est fixée"},{"icon":"heart-rate","label":"Moyen","description":"Attentes floues ou superficielles"},{"icon":"arrow-growth","label":"Élevé","description":"Attentes claires et communiquées"}]}', 'option', NULL, NULL, NULL, 5) ON CONFLICT DO NOTHING;
INSERT INTO question (id, title, competence_id, description, tooltip_data, type, created_at, updated_at, deleted_at, scale) VALUES ('c5e34b76-52d9-467b-aa40-bf1beb05df18', 'Les objectifs de la leçon sont explicités et liés au cours', '8860e659-02da-4d99-abe4-135c25f1c26f', NULL, '{"title":"Objectifs de la leçon","subtitle":"Les objectifs doivent être annoncés et reliés aux activités du cours","items":[{"icon":"chart-down","label":"Faible","description":"Objectifs absents ou peu clairs"},{"icon":"heart-rate","label":"Moyen","description":"Objectifs mentionnés mais peu liés aux activités"},{"icon":"arrow-growth","label":"Élevé","description":"Objectifs clairs et reliés au déroulement du cours"}]}', 'option', NULL, NULL, NULL, 5) ON CONFLICT DO NOTHING;
INSERT INTO question (id, title, competence_id, description, tooltip_data, type, created_at, updated_at, deleted_at, scale) VALUES ('b7cd82e2-306e-467d-912e-bafde90febb4', 'Des questions et stratégies vérifient la compréhension', '8860e659-02da-4d99-abe4-135c25f1c26f', NULL, '{"title":"Vérifier la compréhension","subtitle":"Sans questions ou relances, le niveau de compréhension n''est pas assuré","items":[{"icon":"chart-down","label":"Faible","description":"Peu ou pas de vérification de compréhension"},{"icon":"heart-rate","label":"Moyen","description":"Vérification pour quelques élèves seulement"},{"icon":"arrow-growth","label":"Élevé","description":"Vérification pour la plupart des élèves"}]}', 'option', NULL, NULL, NULL, 5) ON CONFLICT DO NOTHING;
INSERT INTO question (id, title, competence_id, description, tooltip_data, type, created_at, updated_at, deleted_at, scale) VALUES ('21ab1281-4d6a-4d9c-850b-5b852fff7c01', 'La plupart des élèves sont suivis pendant le travail autonome ou en groupe', '8860e659-02da-4d99-abe4-135c25f1c26f', NULL, '{"title":"Suivi pendant le travail autonome ou en groupe","subtitle":"Rester assis sans circuler ne compte pas comme un suivi actif","items":[{"icon":"chart-down","label":"Faible","description":"Peu ou pas de suivi des élèves"},{"icon":"heart-rate","label":"Moyen","description":"Suivi de certains élèves"},{"icon":"arrow-growth","label":"Élevé","description":"Suivi de la plupart des élèves"}]}', 'option', NULL, NULL, NULL, 5) ON CONFLICT DO NOTHING;
INSERT INTO question (id, title, competence_id, description, tooltip_data, type, created_at, updated_at, deleted_at, scale) VALUES ('cb414e34-1681-46ec-8221-812bd849d3cb', 'L''enseignement est adapté au niveau des élèves', '8860e659-02da-4d99-abe4-135c25f1c26f', NULL, '{"title":"Adaptation au niveau des élèves","subtitle":"Sans réexplication ni nouvelles occasions d''apprendre face aux erreurs, l''adaptation est faible","items":[{"icon":"chart-down","label":"Faible","description":"Peu d''adaptation au niveau des élèves"},{"icon":"heart-rate","label":"Moyen","description":"Adaptation partielle"},{"icon":"arrow-growth","label":"Élevé","description":"Adaptation marquée au niveau des élèves"}]}', 'option', NULL, NULL, NULL, 5) ON CONFLICT DO NOTHING;
INSERT INTO question (id, title, competence_id, description, tooltip_data, type, created_at, updated_at, deleted_at, scale) VALUES ('65adb3a6-4fc7-4f1f-8b4c-4c670658127b', 'L''enseignant propose des tâches de pensée critique', '968d595a-d033-4b6c-9758-943cfb6c412c', NULL, '{"title":"Tâches de pensée critique","subtitle":"Sans tâches de réflexion, les élèves écoutent seulement ou répètent mécaniquement","items":[{"icon":"chart-down","label":"Faible","description":"Pas de tâches de pensée critique"},{"icon":"heart-rate","label":"Moyen","description":"Tâches trop simples ou proches des exemples de l''enseignant"},{"icon":"arrow-growth","label":"Élevé","description":"Tâches exigeantes qui appliquent l''apprentissage à de nouvelles situations"}]}', 'option', NULL, NULL, NULL, 5) ON CONFLICT DO NOTHING;
